    </linearGradient>
  </defs>

  <rect width="1280" height="720" fill="url(#bg)"/>
  <rect width="1280" height="720" fill="url(#glow)"/>

  <text x="1230" y="52" text-anchor="end" font-family="'Segoe UI', system-ui, -apple-system, sans-serif" font-size="16" font-weight="600" fill="#5f7189" letter-spacing="2">DISPATCH TMS</text>

  <circle cx="640" cy="280" r="100" fill="url(#circle)" stroke="{$accentBorder}" stroke-width="1.5"/>
  <circle cx="640" cy="280" r="100" fill="none" stroke="{$accent}" stroke-width="0.5" opacity="0.15"/>

  <svg x="580" y="220" width="120" height="120" viewBox="0 0 24 24" fill="none" stroke="{$accent}" stroke-linecap="round" stroke-linejoin="round">
    {$iconInner}
  </svg>

  <text x="640" y="430" text-anchor="middle" font-family="'Segoe UI', system-ui, -apple-system, sans-serif" font-size="38" font-weight="700" fill="{$textColor}">{$escapedTitle}</text>

  <text x="640" y="470" text-anchor="middle" font-family="'Segoe UI', system-ui, -apple-system, sans-serif" font-size="18" font-weight="400" fill="{$textMuted}">{$escapedDesc}</text>

SVG;

if ($category) {
    echo <<<SVG
  <rect x="{$catX}" y="500" width="{$catWidth}" height="34" rx="17" fill="{$accentSoft}" stroke="{$accentBorder}" stroke-width="1"/>
  <text x="640" y="522" text-anchor="middle" font-family="'Segoe UI', system-ui, -apple-system, sans-serif" font-size="14" font-weight="600" fill="{$accent}" letter-spacing="0.5">{$escapedCategory}</text>

SVG;
}

echo <<<SVG
  <rect x="{$badgeX}" y="565" width="{$badgeWidth}" height="36" rx="18" fill="{$badgeBg}" stroke="{$badgeBorder}" stroke-width="1"/>
  <text x="640" y="588" text-anchor="middle" font-family="'Segoe UI', system-ui, -apple-system, sans-serif" font-size="15" font-weight="600" fill="{$badgeColor}" letter-spacing="0.5">{$badgeText}</text>
</svg>
SVG;
